import{_ as o,o as r,c as n,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"文明路线交互沙盘","description":"掠夺路线 × 锚点共生路线 —— 成长曲线、资源逻辑、文明上限的可视化对比推演。","frontmatter":{"title":"文明路线交互沙盘","description":"掠夺路线 × 锚点共生路线 —— 成长曲线、资源逻辑、文明上限的可视化对比推演。"},"headers":[],"relativePath":"sandbox/index.md","filePath":"sandbox/index.md","lastUpdated":null}'),a={name:"sandbox/index.md"};function e(l,t,i,d,g,u){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="文明路线交互沙盘" tabindex="-1">文明路线交互沙盘 <a class="header-anchor" href="#文明路线交互沙盘" aria-label="Permalink to &quot;文明路线交互沙盘&quot;">​</a></h1><p>以<strong>衡元宙</strong>设定为基础的可视化推演工具：左侧调整两条路线的参数，右侧实时呈现<strong>掠夺路线</strong>与<strong>锚点共生路线</strong>的成长曲线、资源存量与文明上限。所有计算都在你的浏览器本地完成，无需后端。</p><iframe src="sandbox.html" style="width:100%;height:900px;border:1px solid var(--vp-c-divider);border-radius:12px;background:#0b1220;" loading="lazy" title="文明路线交互沙盘"></iframe><div class="tip custom-block"><p class="custom-block-title">使用建议</p><ul><li>想体验&quot;短期暴富、长期崩塌&quot;：把<strong>掠夺强度</strong>调高、<strong>内部冲突</strong>调低，观察掠夺路线的峰值与崩塌。</li><li>想体验&quot;稳步上行、集体升维&quot;：开启 <strong>20% 激活战略</strong>，观察共生文明在第 35 纪元后的加速与逐级升维。</li><li>拖动任意滑杆即可实时重算；推演全程确定性，同一组参数永远得到同一结果。</li></ul></div><ul><li><strong>单独打开全屏版</strong>：<a href="sandbox.html" target="_blank" rel="noopener">sandbox.html</a>（可直接双击本地文件运行，也可在手机上打开）</li><li><strong>模型与参数说明</strong>：见沙盘页内底部&quot;模型说明&quot;折叠区。</li><li><strong>设定依据</strong>：《00-衡元宙宇宙总览》《04-反掠夺主义核心论纲》《23-20%激活战略规划》《25-共生反馈循环机制》。</li></ul><h2 id="为什么做这个沙盘" tabindex="-1">为什么做这个沙盘 <a class="header-anchor" href="#为什么做这个沙盘" aria-label="Permalink to &quot;为什么做这个沙盘&quot;">​</a></h2><p><strong>掠夺与共生</strong>是衡元宙的根本矛盾。文字设定可以描述两条路线，但&quot;谁快、谁久、谁更高&quot;需要动态推演才能直观体会：</p><ol><li><strong>成长曲线</strong>：掠夺路线早期陡峭、峰值耀眼，却在资源临界点后不可逆崩塌；锚点共生路线起步平缓，但随升维逐级抬升天花板，最终反超。</li><li><strong>资源逻辑</strong>：掠夺路线的宇宙是&quot;有限猎场&quot;，只出不进、熵增逸散；锚点共生路线的宇宙通过<strong>能量循环</strong>与再生机制自给自足。</li><li><strong>文明上限</strong>：掠夺路线的顶点是位面级——受&quot;本源不纯&quot;瓶颈与法则壁垒封顶；锚点共生路线的顶点是星际共生——<strong>四阶段升维路径</strong>没有终点。</li></ol><p>想深入理解沙盘背后的设定，可从 <a href="../constitution/04-反掠夺主义核心论纲.html">04-反掠夺主义核心论纲</a> 读起。</p>',9)])])}const _=o(a,[["render",e]]);export{p as __pageData,_ as default};
